'use strict';
const app = document.getElementById('app');
let receivedCard=null, sharePending=false, shareRevision=0, activeShare=null;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read = (key, fallback) => { try { return JSON.parse(sessionStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const save = (key, value) => { try { sessionStorage.setItem(key, JSON.stringify(value)); } catch {} };
let signedIn = read('fold-session', false), step = 1, completed = false, previewMode = '비즈니스';
let signup = { id:'', password:'', name:'', email:'', purposes:['비즈니스'] };
let profile = read('fold-profile', { name:'김지우', theme:'blue', photoShape:'rounded', photoSize:'medium', photo:'', fields:[{label:'직업',value:'프로덕트 디자이너',selected:true},{label:'회사',value:'스튜디오 담다',selected:true},{label:'이메일',value:'hello@example.com',selected:true},{label:'전화번호',value:'010-1234-5678',selected:false},{label:'Instagram',value:'@damda.daily',selected:false},{label:'취미',value:'사진 · 러닝 · 커피',selected:false},{label:'Discord',value:'damda_player',selected:false}] });
const arrow = '';
const brand = '<a class="brand" href="#login" aria-label="DamDa 홈"><img src="damda-logo.png" alt="">DamDa<small>명함 교환기</small></a>';
const header = (inside=false) => `<header>${brand}<div class="top-right">${inside?'<span>나의 워크스페이스</span><button class="text-button" data-action="logout">로그아웃</button>':location.hash==='#signup'?'<span>이미 계정이 있나요?</span><a href="#login">로그인</a>':'<span>DamDa이 처음인가요?</span><a href="#signup">회원가입 '+arrow+'</a>'}</div></header>`;
const footer = '<footer class="footer"><span>© 2026 DamDa. All rights reserved.</span><span>나의 정보, 나의 선택.</span></footer>';
function demoCard(mode='비즈니스') { const data = mode==='친구'?['DamDa','사진 찍고, 달리고, 커피를 좋아해요.',['@damda.daily','사진','러닝']]:mode==='게임'?['damda_player','함께 플레이할 다음 친구에게.',['Discord · damda','VALORANT']]:['김지우','프로덕트 디자이너 · 스튜디오 담다',['hello@damda.studio','damda.studio']];return `<div class="business-card"><div class="card-head"><div class="monogram">${mode==='게임'?'I':'이'}</div><span class="card-mark">DamDa / ${mode==='비즈니스'?'WORK':mode==='친구'?'LIFE':'PLAY'}</span></div><h3>${data[0]}</h3><div class="role">${data[1]}</div><div class="card-info">${data[2].map(v=>'<span>'+v+'</span>').join('')}</div></div>`; }
function intro() { return `<section class="intro"><div class="eyebrow">A LITTLE MORE YOU</div><h1>모든 나를 담고,<br><em>필요한 나만</em> 전하세요.</h1><p class="lead">일할 때의 나도, 취미를 나누는 나도.<br>만나는 사람에 맞춰 꺼내는 나만의 명함.</p><div class="showcase"><div class="showcase-top"><span>이런 모습으로 만나요</span><div class="segmented" aria-label="명함 예시">${['비즈니스','친구','게임'].map(m=>`<button data-demo="${m}" class="${m===previewMode?'active':''}" aria-pressed="${m===previewMode}">${m}</button>`).join('')}</div></div><div id="demo-card">${demoCard(previewMode)}</div><p class="privacy-note"><span aria-hidden="true">⌑</span> 내가 선택한 정보만 명함에 담겨요.</p></div><div class="intro-bottom"><span class="mini-lines"><i></i><i></i><i></i></span>하나의 프로필, 다양한 나의 모습</div></section>`; }
function field(label,name,type='text',placeholder='',value='',extra='') {return `<div class="field"><label for="${name}">${label}</label><div class="${type==='password'?'password-wrap':''}"><input id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${extra}>${type==='password'?`<button type="button" class="eye" data-eye="${name}" aria-label="비밀번호 보기">보기</button>`:''}</div></div>`;}
function loginView(){return `<div class="form-panel"><div class="kicker">WELCOME BACK</div><h2>다시 만나 반가워요</h2><p class="sub">나를 전하는 새로운 만남을 시작하세요.</p><form id="login-form">${field('아이디','login-id','text','아이디를 입력해 주세요','','required autocomplete="username"')}${field('비밀번호','login-password','password','비밀번호를 입력해 주세요','','required autocomplete="current-password"')}<div class="row-between"><label class="check-label"><input type="checkbox" id="remember-id">아이디 기억하기</label><button type="button" class="text-button forgot" data-action="help">로그인 도움말</button></div><div id="form-error" role="alert"></div><button class="primary login-submit" type="submit">로그인 <span aria-hidden="true">→</span></button></form><div class="signup-prompt">아직 계정이 없으신가요?<a href="#signup">회원가입</a></div><div class="demo-box"><div><strong>먼저 둘러보고 싶다면</strong>체험 계정 · admin / 1234</div><button type="button" data-action="fill-demo">계정 입력</button></div></div>`;}
function signupView(){ if(completed)return `<div class="form-panel success"><div class="success-icon">✓</div><h2>첫 만남을 준비했어요</h2><p class="sub">${esc(signup.name)}님, DamDa에 오신 걸 환영해요.<br>이제 명함에 담을 정보를 골라보세요.</p><button class="primary" data-action="enter">내 명함 만들기 →</button><p class="hint">체험용 가입이 완료되었어요.<br>입력한 비밀번호는 저장하지 않아요.</p></div>`;return `<div class="form-panel"><div class="steps"><b class="${step===1?'current':''}">1</b><span>계정</span><i></i><b class="${step===2?'current':''}">2</b><span>프로필</span><i></i><b class="${step===3?'current':''}">3</b><span>시작하기</span></div><h2>${['나를 잇는 첫걸음','어떤 이름으로 만날까요?','어떤 만남을 준비하나요?'][step-1]}</h2><p class="sub">${['간단한 정보로 나만의 명함을 시작하세요.','명함에 담을 기본 정보를 알려주세요.','자주 사용할 명함을 골라주세요. 여러 개도 좋아요.'][step-1]}</p><form id="signup-form">${step===1?field('아이디','signup-id','text','영문, 숫자 4자 이상',signup.id,'required minlength="4" maxlength="30" pattern="[A-Za-z0-9_]+" autocomplete="username"')+field('비밀번호','signup-password','password','8자 이상 입력해 주세요',signup.password,'required minlength="8" autocomplete="new-password"')+field('비밀번호 확인','confirm-password','password','비밀번호를 한 번 더 입력해 주세요',signup.password,'required autocomplete="new-password"'):step===2?field('이름 또는 닉네임','signup-name','text','명함에 사용할 이름',signup.name,'required maxlength="30" autocomplete="name"')+field('이메일','signup-email','email','hello@example.com',signup.email,'required autocomplete="email"')+'<p class="hint">이름과 이메일도 명함을 만들 때 공개 여부를 선택할 수 있어요.</p>':`<div class="choice-grid">${['비즈니스','친구','학교','게임'].map((v,i)=>`<label class="choice"><input type="checkbox" name="purpose" value="${v}" ${signup.purposes.includes(v)?'checked':''}>${['일 · 비즈니스','친구 · 취미','학교 · 모임','게임 · 온라인'][i]}</label>`).join('')}</div><div class="policy">이 페이지는 서비스 체험용 목업이에요. 실제 계정은 생성되지 않으며, 프로필은 현재 브라우저 탭에서 유지돼요. 공유 명함은 이 PC에 저장되며 링크를 아는 사람이 열 수 있어요.</div><label class="check-label"><input id="consent" type="checkbox" required>체험용 정보 처리 안내를 확인했어요.</label>`}<div id="form-error" role="alert"></div><div class="step-actions">${step>1?'<button class="secondary" type="button" data-action="previous">이전</button>':''}<button class="primary" type="submit">${step===3?'가입하고 시작하기':'다음'} <span aria-hidden="true">→</span></button></div></form><div class="signup-prompt">이미 계정이 있나요?<a href="#login">로그인</a></div></div>`;}
function card(data=profile){ const fields=data.fields.filter(f=>f.selected);return `<div class="business-card ${['dark','mint'].includes(data.theme)?data.theme:''}"><div class="card-head">${data.photo?`<img class="profile-photo" src="${esc(data.photo)}" alt="내 프로필">`:`<div class="monogram">${esc(data.name.slice(0,1))}</div>`}<span class="card-mark">DamDa / MY CARD</span></div>${data.showName===false?'':`<h3>${esc(data.name)}</h3>`}<div class="card-info">${fields.length?fields.map(f=>`<span><small>${esc(f.label)}</small>　${esc(f.value)}</span>`).join(''):'<span>공개할 정보를 선택해 주세요.</span>'}</div></div>`;}
function dashboard(){return `${header(true)}<main class="workspace"><div class="workspace-title"><span class="eyebrow">MY CARD</span><h1>오늘은 어떤 나를 전할까요?</h1><p>공유하고 싶은 정보만 골라 나만의 명함을 완성하세요.</p></div><div class="workspace-grid"><section class="surface"><h2>내 정보</h2><p class="sub">체크한 항목만 명함과 공유 링크에 포함돼요.</p><div class="photo-upload"><label for="photo">프로필 사진</label><input type="file" id="photo" accept="image/png,image/jpeg,image/webp"><button class="text-button" data-action="remove-photo">사진 없이</button></div><div class="info-row"><input type="checkbox" id="show-name" aria-label="이름 공개" ${profile.showName===false?'':'checked'}><label for="profile-name">이름</label><input type="text" id="profile-name" value="${esc(profile.name)}" maxlength="30"></div>${profile.fields.map((f,i)=>`<div class="info-row"><input type="checkbox" data-select="${i}" aria-label="${esc(f.label)} 공개" ${f.selected?'checked':''}><label for="info-${i}">${esc(f.label)}</label><input type="text" id="info-${i}" data-field="${i}" value="${esc(f.value)}" maxlength="120"></div>`).join('')}<form id="custom-form" class="custom-add"><input aria-label="추가할 항목 이름" name="label" placeholder="항목 이름 (예: GitHub)" maxlength="20" required><button type="submit" class="secondary">+ 항목 추가</button></form></section><section class="surface preview-column"><div class="row-between"><h2>명함 미리보기</h2><span class="preview-label">LIVE PREVIEW</span></div><p class="sub">선택한 정보가 실시간으로 반영돼요.</p><div class="segmented presets" aria-label="공개 정보 프리셋">${['비즈니스','친구','학교','게임'].map(v=>`<button data-preset="${v}">${v}</button>`).join('')}</div><div class="template-options" aria-label="명함 디자인">${[['light','#ffffff','화이트'],['dark','#192b50','미드나이트'],['mint','#e7f6f1','민트']].map(([v,c,l])=>`<button class="swatch" aria-label="${l} 디자인" aria-pressed="${profile.theme===v}" data-theme="${v}" style="background:${c}"></button>`).join('')}</div><div id="live-card">${card()}</div><button class="primary" data-action="share">명함 만들고 공유하기 ${arrow}</button><div id="share-result" aria-live="polite"></div><p class="hint">선택한 정보와 사진으로 명함을 만들어요. 받은 사람은 로그인 없이 저장할 수 있어요.</p></section></div></main>${footer}`;}
function render(){const route=location.hash.split('?')[0];if(route==='#card'){renderReceived();return;}
if(route==='#home'){if(!signedIn){location.hash='login';return;}app.innerHTML=dashboard();}else{app.innerHTML=header()+`<main class="auth-layout">${intro()}${route==='#signup'?signupView():loginView()}</main>`+footer;try{const remembered=localStorage.getItem('fold-remember-id');if(remembered&&document.getElementById('login-id')){document.getElementById('login-id').value=remembered;document.getElementById('remember-id').checked=true;}}catch{}} }
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3000);}
function error(message){document.getElementById('form-error').innerHTML=`<div class="error">${esc(message)}</div>`;}
function updateCard(){shareRevision++;activeShare=null;save('fold-profile',profile);document.getElementById('live-card').innerHTML=card();const r=document.getElementById('share-result');if(r)r.innerHTML='';}
app.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.eye){const input=document.getElementById(t.dataset.eye);input.type=input.type==='password'?'text':'password';t.textContent=input.type==='password'?'보기':'숨기기';t.setAttribute('aria-label','비밀번호 '+t.textContent);return;}if(t.dataset.demo){previewMode=t.dataset.demo;document.querySelectorAll('[data-demo]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',b===t);});const preview=document.getElementById('demo-card');preview.innerHTML=demoCard(previewMode);return;}if(t.dataset.theme){profile.theme=t.dataset.theme;document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',b===t));updateCard();return;}if(t.dataset.preset){shareRevision++;const selections={비즈니스:['직업','회사','이메일'],친구:['Instagram','취미'],학교:['이메일','전화번호'],게임:['Discord']};profile.fields.forEach(f=>f.selected=selections[t.dataset.preset].includes(f.label));save('fold-profile',profile);render();document.querySelector(`[data-preset="${t.dataset.preset}"]`).classList.add('active');toast(t.dataset.preset+'용 공개 정보를 선택했어요.');return;}switch(t.dataset.action){case 'download-png':downloadReceived('png',t);break;case 'download-vcf':downloadReceived('vcf',t);break;case 'retry-card':renderReceived();break;case 'fill-demo':document.getElementById('login-id').value='admin';document.getElementById('login-password').value='1234';document.querySelector('.login-submit').focus();break;case 'help':toast('체험 계정은 admin / 1234예요. 회원가입도 체험할 수 있어요.');break;case 'previous':captureSignup();step--;render();break;case 'enter':signedIn=true;save('fold-session',true);location.hash='home';break;case 'logout':signedIn=false;save('fold-session',false);location.hash='login';break;case 'remove-photo':profile.photo='';document.getElementById('photo').value='';updateCard();break;case 'share':share();break;}});
function captureSignup(){if(step===1){signup.id=document.getElementById('signup-id').value.trim();signup.password=document.getElementById('signup-password').value;}if(step===2){signup.name=document.getElementById('signup-name').value.trim();signup.email=document.getElementById('signup-email').value.trim();}}
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){const id=document.getElementById('login-id').value.trim(),password=document.getElementById('login-password').value;if(id!=='admin'||password!=='1234'){error('아이디 또는 비밀번호를 확인해 주세요. 체험 계정은 admin / 1234예요.');return;}try{if(document.getElementById('remember-id').checked)localStorage.setItem('fold-remember-id',id);else localStorage.removeItem('fold-remember-id');}catch{}signedIn=true;save('fold-session',true);location.hash='home';}else if(e.target.id==='signup-form'){captureSignup();if(step===1){if(signup.id.toLowerCase()==='admin'){error('admin은 체험용 계정이에요. 다른 아이디를 입력해 주세요.');return;}if(signup.password!==document.getElementById('confirm-password').value){error('비밀번호가 일치하지 않아요.');return;}}if(step===2&&!signup.name){error('이름 또는 닉네임을 입력해 주세요.');return;}if(step<3){step++;render();}else{signup.purposes=Array.from(document.querySelectorAll('[name=purpose]:checked'),x=>x.value);if(!signup.purposes.length){error('한 가지 이상의 만남을 선택해 주세요.');return;}profile.name=signup.name;profile.fields.forEach(f=>{f.value=f.label==='이메일'?signup.email:'';f.selected=f.label==='이메일';});profile.photo='';profile.nickname='';profile.nameMode='name';profile.photoShape='circle';profile.photoSize='medium';save('fold-profile',profile);signup.password='';completed=true;render();}}else if(e.target.id==='custom-form'){const label=new FormData(e.target).get('label').trim();if(!label)return;if(profile.fields.length>=20){toast('항목은 최대 20개까지 추가할 수 있어요.');return;}if(profile.fields.some(f=>f.label===label)){toast('이미 등록된 항목이에요.');return;}profile.fields.push({label,value:'',selected:true});save('fold-profile',profile);render();document.getElementById('info-'+(profile.fields.length-1)).focus();}});
app.addEventListener('input',e=>{const t=e.target;if(t.dataset.field!==undefined){profile.fields[Number(t.dataset.field)].value=t.value;updateCard();}if(t.id==='profile-name'){profile.name=t.value;updateCard();}});
app.addEventListener('change',e=>{const t=e.target;if(t.dataset.select!==undefined){profile.fields[Number(t.dataset.select)].selected=t.checked;updateCard();}if(t.id==='show-name'){profile.showName=t.checked;updateCard();}if(t.id==='photo'&&t.files[0]){const file=t.files[0];if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('2MB 이하의 PNG, JPG, WebP 사진을 선택해 주세요.');t.value='';return;}const reader=new FileReader();reader.onload=()=>{profile.photo=reader.result;updateCard();};reader.readAsDataURL(file);}});
window.addEventListener('hashchange',()=>{shareRevision++;render();window.scrollTo(0,0);});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_selected_card_fields',description:'현재 명함에서 공개하기로 선택한 정보만 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!signedIn)throw new Error('먼저 로그인해 주세요.');if(!input||Object.keys(input).length)throw new Error('빈 객체를 입력해 주세요.');return {fields:profile.fields.filter(f=>f.selected).map(({label,value})=>({label,value}))};}})).catch(()=>{});}catch{}}
